files.src/registry/cache.ts:
import { fetchScooter, type ScooterRecord } from './client.js';

const TTL_MS = 10 * 60_000;
const entries = new Map<string, { at: number; rec: ScooterRecord }>();

export async function getScooter(id: string): Promise<ScooterRecord> {
  const hit = entries.get(id);
  if (hit && Date.now() - hit.at < TTL_MS) return hit.rec;
  const rec = await fetchScooter(id);
  entries.set(id, { at: Date.now(), rec });
  return rec;
}

