import { LOW_SOC } from './battery.js';

const CLEAR_SOC = 20;
const active = new Set<string>();

export function updateLowBattery(scooterId: string, soc: number): boolean {
  if (soc <= LOW_SOC) active.add(scooterId);
  else if (soc >= CLEAR_SOC) active.delete(scooterId);
  return active.has(scooterId);
}

