import { ZONES_URL, downloadZones } from './loader.js';

let cached: { etag: string; zones: unknown } | undefined;

export async function zones(): Promise<unknown> {
  const head = await fetch(ZONES_URL, { method: 'HEAD' });
  if (cached && head.headers.get('etag') === cached.etag) return cached.zones;
  cached = await downloadZones();
  return cached.zones;
}

