import { sendAlert } from './send.js';

export async function sendWithRetry(url: string, body: string, headers: Record<string, string>, attempts = 6) {
  for (let i = 0; ; i++) {
    try { return await sendAlert(url, body, headers); }
    catch (err) { if (i + 1 >= attempts) throw err; }
    await new Promise((r) => setTimeout(r, 1000 * 2 ** i));
  }
}

