import type { FastifyInstance } from 'fastify';
import type { Pool } from 'pg';
import { lastFrame } from './last-frame.js';

export async function statusRoutes(app: FastifyInstance, { pool }: { pool: Pool }) {
  app.get<{ Params: { id: string } }>('/scooters/:id/status', async (req, reply) => {
    const frame = await lastFrame(pool, req.params.id);
    return frame ?? reply.code(404).send();
  });
}

